class Solution:
    def generateParenthesis(self, n: int) -> list[str]:
        path = []
        ans = []

        def choose(opens, closes):
            if opens < closes or opens > n or closes > n:
                return

            if opens + closes == 2*n:
                ans.append("".join(path[:]))
                return

            for p in "()":
                path.append(p)
                if p == "(":
                    choose(opens + 1, closes)
                else:
                    choose(opens, closes + 1)
                path.pop()

        choose(0, 0)
        return ans
